"""Declarative form-field validators for ``Field(..., validators=[...])``.

These are **declarative markers**, not Python functions that run at request time:
the compiler reads them from your ``build()`` and emits inert JS checks (no user
code crosses into the runtime), so they stay inside the no-injection rule.

Available::

    required                       # non-empty
    email                          # a valid email address
    numeric                        # a number, nothing else
    is_date                        # a real date (ISO text read strictly)
    min_length(n, message=...)     # at least n characters
    max_length(n, message=...)     # at most n characters
    min_value(n, message=...)      # a number no smaller than n
    max_value(n, message=...)      # a number no larger than n
    min_date(iso, message=...)     # a day on or after iso ("1970-01-01")
    max_date(iso, message=...)     # a day on or before iso
    pattern(regex, message=...)    # matches a regular expression
    matches(field, message=...)    # equals another field's value (confirm password)

``required`` / ``email`` / ``numeric`` / ``is_date`` are used bare — or called,
if you want a ``message``. The rest are always called. ``message`` overrides the
default error text. Used only inside ``Field``; never executed in Python.

**Every rule but ``required`` passes an empty value.** That is what lets a field
be optional and still validated when filled; make it mandatory with ``required``
alongside.

``min_value`` / ``max_value`` also reject a value that is not a number at all,
rather than letting "abc" through because it compares as neither larger nor
smaller. The bound is the claim being made, and "abc" does not satisfy it.

The three date rules read a value one way. Text shaped like an ISO date
(``"2025-12-16"``, ``"2025-12-16T14:30"``, and ``"2025"`` too) must be a real
day or wall-clock date-time, so ``"2025-02-30"`` fails ``is_date`` rather than
reading as 2 March; a digit from another script (``"２０２５-01-01"``) fails
too. Other text is a date if the browser can read it (``"12/31/2025"``), read
the browser's way. ``min_date`` and ``max_date`` compare whole days,
inclusive, so a value is on the same side of its bound in every time zone;
like ``max_value`` with ``"abc"``, they refuse ISO-shaped text that names no
day. Their ``iso`` must be an ISO date: anything else is a compile error.
"""
from __future__ import annotations

from typing import Any


class _Validator:
    """A marker for one validation rule. Parsed declaratively by the compiler
    (its ``kind`` + ``params`` become a safe JS descriptor); never run here."""

    def __init__(self, kind: str, **params: Any):
        self.kind = kind
        self.params = params


#: Require a non-empty value.
required = _Validator("required")

#: Require a syntactically valid email address.
email = _Validator("email")


def min_length(n: int, *, message: str | None = None) -> _Validator:
    """At least ``n`` characters."""
    return _Validator("min", n=n, message=message)


def max_length(n: int, *, message: str | None = None) -> _Validator:
    """At most ``n`` characters."""
    return _Validator("max", n=n, message=message)


def pattern(regex: str, message: str | None = None) -> _Validator:
    """Match the regular expression ``regex`` (a string)."""
    return _Validator("pattern", regex=regex, message=message)


def matches(field: str, message: str | None = None) -> _Validator:
    """Equal another field's current value — e.g. a confirm-password field."""
    return _Validator("matches", field=field, message=message)


#: Require a number and nothing else. Bare, or called for a custom message.
numeric = _Validator("numeric", message=None)

#: Require a real date: ISO text (an ``<input type="date">`` gives
#: ``YYYY-MM-DD``) must name a day that exists, other text one the browser
#: can read. Named ``is_date`` rather than ``date`` so it cannot be confused
#: with :class:`datetime.date` in a file that imports both.
is_date = _Validator("date", message=None)


def min_value(n: float, *, message: str | None = None) -> _Validator:
    """A number no smaller than ``n``. Rejects a non-number too."""
    return _Validator("minv", n=n, message=message)


def max_value(n: float, *, message: str | None = None) -> _Validator:
    """A number no larger than ``n``. Rejects a non-number too."""
    return _Validator("maxv", n=n, message=message)


def min_date(iso: str, *, message: str | None = None) -> _Validator:
    """A day on or after ``iso``, an ISO date such as ``"2000-01-01"``.
    Compared by day, so a value's time and the viewer's zone never move it
    across the bound."""
    return _Validator("mind", iso=iso, message=message)


def max_date(iso: str, *, message: str | None = None) -> _Validator:
    """A day on or before ``iso``, an ISO date: ``"2025-12-16T23:59"`` is
    still on or before ``"2025-12-16"``."""
    return _Validator("maxd", iso=iso, message=message)
